DO $rollback$
BEGIN
    IF EXISTS (SELECT 1 FROM config_audit_event WHERE entity_type = 'PRACTICE_USAGE') THEN
        RAISE WARNING 'The audit entity-type constraint remains widened because append-only history contains PRACTICE_USAGE rows';
        RETURN;
    END IF;

    ALTER TABLE config_audit_event DROP CONSTRAINT ck_config_audit_event_entity_type;
    ALTER TABLE config_audit_event ADD CONSTRAINT ck_config_audit_event_entity_type
        CHECK (entity_type IN (
            'PRACTICE_REVIEW_SETTINGS', 'AGENT_BINDING', 'AGENT_CONFIG', 'AI_CONFIG_BINDING',
            'WORKSPACE_ROLE', 'WORKSPACE_FEATURES', 'WORKSPACE_STATUS',
            'WORKSPACE_TOKEN', 'WORKSPACE_VISIBILITY', 'PRACTICE_ACTIVE',
            'PRACTICE_DEFINITION', 'PRACTICE_AREA', 'CURATED_PRACTICE', 'CURATED_PRACTICE_AREA',
            'WORKSPACE_INSTANCE_LLM_BUDGET', 'WORKSPACE_OWN_PROVIDER_LLM_BUDGET',
            'WORKSPACE_LLM_BUDGET', 'WORKSPACE_BYO_LLM_BUDGET',
            'WORKSPACE_LLM_CONNECTION', 'WORKSPACE_LLM_MODEL'
        ));
END
$rollback$;

DO $rollback$
BEGIN
    IF to_regclass('workspace_agent_binding') IS NOT NULL THEN
        UPDATE workspace_agent_binding
        SET purpose = 'PRACTICE_DETECTION'
        WHERE purpose = 'PRACTICE_REVIEW';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'agent_job'
          AND column_name = 'purpose'
    ) THEN
        UPDATE agent_job
        SET purpose = 'PRACTICE_DETECTION'
        WHERE purpose = 'PRACTICE_REVIEW';
    END IF;

END
$rollback$;

